SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'eu_threshold_value_anhb23', 'EU-Schwellenwert nach Anh. B.2.3 (aus dem Organisationstyp; Stand VO (EU) 2019/1828, ab 01.01.2020)', 'number', 'EUR', false, 'Anhang B.2.3 (§ 106 GWB)', 'Plan 3: Tab.-Zwilling neben dem eingetragenen eu_threshold_value (konsumiert von M820-10, gelesen von REQ-07 — Umbindung STAGED m820_1-E-1); 139.000 € für oberste/obere Bundesbehörden, 214.000 € für alle anderen; die Zuordnung der übrigen Organisationstypen zu "für alle anderen" ist m820_1-J-3; der Wert ist zeitgebunden (alle zwei Jahre neu festgesetzt — m820_1-J-1). Abgleich → eu_threshold_konsistent_code (M820-09-D3).', 'imported_unverified', 'Die Höhe der Schwellenwerte wird über eine Verweisung auf die jeweils aktuelle EU-Verordnung bestimmt. Die Schwellenwerte werden von der Europäischen Union alle zwei Jahre festgesetzt. Die EU-Schwellenwerte betragen laut Verordnung (EU) 2019/1828 vom 30.10.2019 ab dem 01.01.2020 für Planungsleistungen von Auftraggebern: — I der obersten oder oberen Bundesbehörden oder vergleichbarer Institutionen $139.000 €$, — - für alle anderen $214.000 €$.', 'lookup_fill', '{"source_label":"Anh. B.2.3 — Verordnung (EU) 2019/1828, ab 01.01.2020"}'::jsonb, '{"table_code":"ANHB23","role":"value","keys":[{"column":"organisation","from_symbol":"client_organization_type"}],"value":"schwellenwert_eur"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'eu_threshold_value_anhb23') AND w.code = 'M820-09' AND s.code = 'DWA-M-820-1';
