SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'eu_threshold_verordnung_anhb23', 'Rechtsgrundlage des EU-Schwellenwerts (Verordnung, wie im Merkblatt gedruckt)', 'text', NULL, false, 'Anhang B.2.3; Anhang B.1.1', 'Plan 3: die im Merkblatt gedruckte Verordnung zum Schwellenwert (Textzwilling zur Nachvollziehbarkeit der Ausgabe); eine neuere Verordnung ist eine neue Tabellen-Edition, nie eine Änderung aus dem Gedächtnis (m820_1-J-1).', 'imported_unverified', 'Die Höhe der Schwellenwerte wird über eine Verweisung auf die jeweils aktuelle EU-Verordnung bestimmt. Die Schwellenwerte werden von der Europäischen Union alle zwei Jahre festgesetzt. Die EU-Schwellenwerte betragen laut Verordnung (EU) 2019/1828 vom 30.10.2019 ab dem 01.01.2020 für Planungsleistungen von Auftraggebern: — Die EU-Schwellenwerte werden von der EU-Kommission alle zwei Jahre geprüft und durch Verordnung festgelegt.', 'lookup_fill', '{"source_label":"Anh. B.2.3"}'::jsonb, '{"table_code":"ANHB23","role":"value","keys":[{"column":"organisation","from_symbol":"client_organization_type"}],"value":"verordnung"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'eu_threshold_verordnung_anhb23') AND w.code = 'M820-09' AND s.code = 'DWA-M-820-1';
