SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'eu_threshold_konsistent_code', 'Eingetragener EU-Schwellenwert = Anh. B.2.3 (1 = ja, 0 = Abweichung)', 'number', NULL, false, 'Anhang B.2.3', 'Plan 3: Ausgabe der Gleichung M820-09-D3 (eu_threshold_value == eu_threshold_value_anhb23); ein Gate auf diesen Wert ist STAGED (m820_1-G-2).', 'imported_unverified', 'In § 106 GWB ist festgelegt, dass das GWB und in Folge die VgV nur gelten, soweit der geschätzte Auftragswert die EU-Schwellenwerte erreicht oder überschreitet. — Die Höhe der Schwellenwerte wird über eine Verweisung auf die jeweils aktuelle EU-Verordnung bestimmt. Die Schwellenwerte werden von der Europäischen Union alle zwei Jahre festgesetzt. Die EU-Schwellenwerte betragen laut Verordnung (EU) 2019/1828 vom 30.10.2019 ab dem 01.01.2020 für Planungsleistungen von Auftraggebern:', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'eu_threshold_konsistent_code') AND w.code = 'M820-09' AND s.code = 'DWA-M-820-1';
