INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'lose', 'Lose (Teilaufträge) nach § 3 Abs. 9 VgV', 'json', NULL, false, 'Anhang B.2.4 (§ 3 Abs. 9 VgV)', 'Plan 3: Zeilen je Los (Art, Nettowert, Loseausnahme); Grenze je Los aus S3_9_VGV; Σ / Abgleich / Anteil / Maximum / Verletzungen → lose_* (M820-09-D8 … D13, D15), loseausnahme_code (M820-09-D14; Anteil auf estimated_engineering_fee bezogen) als abgeleiteter Zwilling zum manuellen Boolean loseausnahme_applicable — Umstellung und REQ-24 (heute leere Bedingung auf M820-04) STAGED (m820_1-D-11, G-4).', 'imported_unverified', 'Die Aufteilung in Lose regelt § 3 Abs .9 VgV : — ,,Der [...] Auftraggeber kann bei der Vergabe einzelner Lose von Absatz 7 Satz 3 sowie Absatz 8 abweichen, wenn der geschätzte Nettowert des betreffenden Loses bei Liefer- und Dienstleistungen unter 80000 Euro und bei Bauleistungen unter 1 Million Euro liegt und die Summe der Nettowerte dieser Lose 20 Prozent des Gesamtwertes aller Lose nicht übersteigt." — Soweit also die Teilaufträge insgesamt $20 \%$ des Gesamtauftragswerts und je Teileauftrag 80.000 € nicht überschreiten, können diese nach nationalem Recht vergeben werden.', 'register', '{"title":"Lose (Teilaufträge) — Loseausnahme nach § 3 Abs. 9 VgV","subtitle":"Anhang B.2.4 — je Los Art, geschätzter Nettowert und ob es nach § 3 Abs. 9 VgV national vergeben werden soll; Grenze je Los aus der Tabelle, Anteil der ausgenommenen Lose am Gesamtwert aller Lose","add_label":"+ Los","placement":"section","columns":[{"key":"los","label":"Los / Teilauftrag","type":"text","required":true},{"key":"art","label":"Art","type":"enum","required":true,"options":["dienstleistung","bau"],"option_labels":{"dienstleistung":"Liefer- und Dienstleistungen (unter 80000 Euro)","bau":"Bauleistungen (unter 1 Million Euro)"}},{"key":"netto_wert_eur","label":"Geschätzter Nettowert","type":"number","unit":"EUR","required":true,"min":0,"aria_label":"geschätzter Nettowert des Loses"},{"key":"ausnahme","label":"Loseausnahme (national vergeben)","type":"boolean"},{"key":"grenze_eur","label":"Grenze je Los (§ 3 Abs. 9 VgV)","type":"derived","expr":"if(art == ''dienstleistung'', lookup(''S3_9_VGV'', ''los_dienstleistung'', ''wert''), lookup(''S3_9_VGV'', ''los_bau'', ''wert''))","unit":"EUR"},{"key":"unter_grenze","label":"unter der Grenze","type":"derived","expr":"if(netto_wert_eur < grenze_eur, 1, 0)","display":"badge","value_labels":{"0":"Losgrenze erreicht oder überschritten","1":"unter der Losgrenze"}}],"footer":["lose_count","lose_gesamt_eur","lose_gesamt_ok","lose_ausnahme_sum_eur","lose_ausnahme_anteil_pct","lose_ausnahme_max_eur","lose_ausnahme_verletzt","loseausnahme_code"],"note":",,Der [...] Auftraggeber kann bei der Vergabe einzelner Lose von Absatz 7 Satz 3 sowie Absatz 8 abweichen, wenn der geschätzte Nettowert des betreffenden Loses bei Liefer- und Dienstleistungen unter 80000 Euro und bei Bauleistungen unter 1 Million Euro liegt und die Summe der Nettowerte dieser Lose 20 Prozent des Gesamtwertes aller Lose nicht übersteigt.\" Soweit also die Teilaufträge insgesamt $20 \\%$ des Gesamtauftragswerts und je Teileauftrag 80.000 € nicht überschreiten, können diese nach nationalem Recht vergeben werden. Bezugsgröße des Anteils = der geschätzte Netto-Gesamtwert (estimated_engineering_fee, M820-01); die Σ der eingetragenen Lose wird daneben angezeigt und mit lose_gesamt_ok abgeglichen (m820_1-J-7); \"unter\" = strenge Grenze je Los (m820_1-J-6)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'lose') AND w.code = 'M820-09' AND s.code = 'DWA-M-820-1';
