SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'lose_count', 'Anzahl erfasster Lose', 'number', NULL, false, 'Anhang B.2.4', 'Plan 3: Ausgabe der Gleichung M820-09-D8 (count_rows über lose).', 'imported_unverified', 'Die Aufteilung in Lose regelt § 3 Abs .9 VgV :', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
