SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'lose_gesamt_eur', 'Gesamtwert aller Lose (Σ Nettowerte)', 'number', 'EUR', false, 'Anhang B.2.4 (§ 3 Abs. 9 VgV)', 'Plan 3: Ausgabe der Gleichung M820-09-D9 (sum_rows über lose.netto_wert_eur) — Anzeige-Zwilling zum geschätzten Netto-Gesamtwert estimated_engineering_fee (m820_1-D-25 / J-7); Abgleich → lose_gesamt_ok.', 'imported_unverified', ',,Der [...] Auftraggeber kann bei der Vergabe einzelner Lose von Absatz 7 Satz 3 sowie Absatz 8 abweichen, wenn der geschätzte Nettowert des betreffenden Loses bei Liefer- und Dienstleistungen unter 80000 Euro und bei Bauleistungen unter 1 Million Euro liegt und die Summe der Nettowerte dieser Lose 20 Prozent des Gesamtwertes aller Lose nicht übersteigt."', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'lose_gesamt_eur') AND w.code = 'M820-09' AND s.code = 'DWA-M-820-1';
