SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'lose_gesamt_ok', 'Σ Lose = geschätzter Netto-Gesamtwert (1 = ja, 0 = Abweichung)', 'number', NULL, false, 'Anhang B.2.4 (§ 3 Abs. 9 VgV); § 8.5', 'Plan 3: Ausgabe der Gleichung M820-09-D15 (|Σ Lose − estimated_engineering_fee| < 0,005); zeigt, ob der "Gesamtwert aller Lose" (L1366) und der "Gesamtauftragswert" (L1368) übereinstimmen (m820_1-J-7).', 'imported_unverified', ',,Der [...] Auftraggeber kann bei der Vergabe einzelner Lose von Absatz 7 Satz 3 sowie Absatz 8 abweichen, wenn der geschätzte Nettowert des betreffenden Loses bei Liefer- und Dienstleistungen unter 80000 Euro und bei Bauleistungen unter 1 Million Euro liegt und die Summe der Nettowerte dieser Lose 20 Prozent des Gesamtwertes aller Lose nicht übersteigt." — Soweit also die Teilaufträge insgesamt $20 \%$ des Gesamtauftragswerts und je Teileauftrag 80.000 € nicht überschreiten, können diese nach nationalem Recht vergeben werden.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'lose_gesamt_ok') AND w.code = 'M820-09' AND s.code = 'DWA-M-820-1';
