SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'loseausnahme_code', 'Loseausnahme nach § 3 Abs. 9 VgV eingehalten (1 = jedes ausgenommene Los unter der Grenze UND Anteil ≤ 20 Prozent, 0 = nein)', 'number', NULL, false, 'Anhang B.2.4 (§ 3 Abs. 9 VgV)', 'Plan 3: Ausgabe der Gleichung M820-09-D14; Zwilling zum manuellen Boolean loseausnahme_applicable (konsumiert von M820-10) — Umstellung und REQ-24 STAGED (m820_1-D-11, G-4). Anteil bezogen auf estimated_engineering_fee (L1368); ohne eingetragene Lose bleibt der Wert offen (kein Phantom-Bestehen).', 'imported_unverified', ',,Der [...] Auftraggeber kann bei der Vergabe einzelner Lose von Absatz 7 Satz 3 sowie Absatz 8 abweichen, wenn der geschätzte Nettowert des betreffenden Loses bei Liefer- und Dienstleistungen unter 80000 Euro und bei Bauleistungen unter 1 Million Euro liegt und die Summe der Nettowerte dieser Lose 20 Prozent des Gesamtwertes aller Lose nicht übersteigt." — Soweit also die Teilaufträge insgesamt $20 \%$ des Gesamtauftragswerts und je Teileauftrag 80.000 € nicht überschreiten, können diese nach nationalem Recht vergeben werden.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'loseausnahme_code') AND w.code = 'M820-09' AND s.code = 'DWA-M-820-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'min_annual_revenue_multiplier_max', 'Höchstzulässiger Mindestjahresumsatz-Faktor (2 nach § 45 Abs. 2 VgV; 1,5 bei großen, langlaufenden Projekten — "sollte")', 'number', NULL, false, 'Anhang E.1.4.1 (§ 45 Abs. 2 VgV)', 'Plan 3: Grenzwert aus E1_4_1_UMSATZ zum Boolean large_long_project (der Boolean ist kein Formeleingang — die Tabelle schlüsselt auf den stringifizierten Wert); Prüfung → min_annual_revenue_multiplier_ok (M820-13-D1); die 1,5 ist eine Empfehlung ("sollte", Tabelle anhaltswert — m820_1-O-1), REQ-12 (≤ 2,0) bleibt; das schärfere Gate ist STAGED (m820_1-G-7).', 'imported_unverified', 'Als Mindestjahresumsatz nach § 45 Abs .2 VgV darf der Auftraggeber nicht mehr als das Zweifache des geschätzten Auftragswerts verlangen. — Bei großen, langlaufenden Projekten sollte das geforderte Verhältnis Jahresumsatz zu Jahresauftragswert den Faktor 1,5 nicht überschreiten.', 'lookup_fill', '{"source_label":"Anh. E.1.4.1 (§ 45 Abs. 2 VgV / Faktor 1,5)"}'::jsonb, '{"table_code":"E1_4_1_UMSATZ","role":"limit","keys":[{"column":"grossprojekt","from_symbol":"large_long_project"}],"value":"faktor_max"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'min_annual_revenue_multiplier_max') AND w.code = 'M820-13' AND s.code = 'DWA-M-820-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'min_annual_revenue_multiplier_ok', 'Geforderter Mindestjahresumsatz-Faktor ≤ Anh. E.1.4.1 (1 = ja, 0 = überschritten)', 'number', NULL, false, 'Anhang E.1.4.1', 'Plan 3: Ausgabe der Gleichung M820-13-D1 (min_annual_revenue_multiplier <= min_annual_revenue_multiplier_max).', 'imported_unverified', 'Bei großen, langlaufenden Projekten sollte das geforderte Verhältnis Jahresumsatz zu Jahresauftragswert den Faktor 1,5 nicht überschreiten.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'min_annual_revenue_multiplier_ok') AND w.code = 'M820-13' AND s.code = 'DWA-M-820-1';
UPDATE fields f SET widget = 'register', ui_config = '{"title":"Zuschlagskriterien","subtitle":"Anhang E.2 — Kriterien mit Gewichtung (§ 127 GWB: spätestens mit der Aufforderung zur Angebotsabgabe anzugeben)","add_label":"+ Zuschlagskriterium","placement":"bottom","columns":[{"key":"kriterium","label":"Kriterium","type":"enum","required":true,"options":["Schlüsselpersonal","Örtliche Bauüberwachung","Organisation der Aufgabenverteilung beim Bieter","Darstellung der Projektorganisation","Analyse der Aufgabenstellung durch den Bieter","Darstellung der Dokumentation des konkreten Projekts","Preis"]},{"key":"gewichtung","label":"Gewichtung (%)","type":"number","unit":"%","required":true,"min":0,"max":100,"width":"w-28","aria_label":"Gewichtung des Kriteriums in Prozent"},{"key":"anmerkung","label":"Anmerkung","type":"text"},{"key":"ist_preis","label":"Preis","type":"derived","expr":"if(kriterium == ''Preis'', 1, 0)","display":"badge","value_labels":{"0":"","1":"Preiskriterium (E.2.8)"}}],"footer":["award_weight_sum_pct","price_weight_calc_pct","qualitaets_kriterien_count"],"note":"Der Auftraggeber ist verpflichtet, spätestens bei der Aufforderung zur Angebotsabgabe, besser bereits bei der Bekanntmachung, die Zuschlagskriterien und deren Gewichtung anzugeben (§ 127 GWB ). Der Auftraggeber kann bei der Vergabe von Ingenieurleistungen auch den Preis werten, muss es jedoch nicht. Wird der Preis gewertet, sollte seine Wertung aber nicht ein so hohes Gewicht erlangen, dass der Preis allein ausschlaggebend für die Vergabeentscheidung wird, weil allein über den Preiswettbewerb keine qualitätsvollen Ingenieurleistungen zu erlangen sind. Alternative Vorgehensweise: Der Auftraggeber darf nach § 58 Abs. 2 VgV einen Festpreis vorgeben. Die Festpreisvorgabe muss HOAI-konform sein. Der Preis ist in diesem Fall kein Zuschlagskriterium mehr. Eine Summe von 100 % nennt das Merkblatt nicht (m820_1-F-1) — die Σ wird nur angezeigt."}'::jsonb, lookup = NULL, visible_when = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'award_criteria_list' AND w.code = 'M820-14' AND s.code = 'DWA-M-820-1' AND f.active;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'award_weight_sum_pct', 'Σ Gewichtung der Zuschlagskriterien', 'number', '%', false, '§ 8.10.3.3 (§ 127 GWB); Anhang E.2', 'Plan 3: Ausgabe der Gleichung M820-14-D1 (sum_rows über award_criteria_list.gewichtung); eine Soll-Summe druckt das Merkblatt nicht (m820_1-F-1).', 'imported_unverified', 'Der Auftraggeber ist verpflichtet, spätestens bei der Aufforderung zur Angebotsabgabe, besser bereits bei der Bekanntmachung, die Zuschlagskriterien und deren Gewichtung anzugeben (§ 127 GWB ).', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'award_weight_sum_pct') AND w.code = 'M820-14' AND s.code = 'DWA-M-820-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'price_weight_calc_pct', 'Gewichtung des Preiskriteriums aus dem Register (Σ der Preis-Zeilen)', 'number', '%', false, 'Anhang E.2.8', 'Plan 3: Ausgabe der Gleichung M820-14-D2 (Σ gewichtung der Zeilen mit kriterium = Preis); Zwilling zum manuellen price_weight_percent (konsumiert von M820-19, gelesen von REQ-15) — Umstellung STAGED (m820_1-D-12, G-1); bei Festpreis ausgeblendet (L1698).', 'imported_unverified', 'Der Auftraggeber kann bei der Vergabe von Ingenieurleistungen auch den Preis werten, muss es jedoch nicht. Wird der Preis gewertet, sollte seine Wertung aber nicht ein so hohes Gewicht erlangen, dass der Preis allein ausschlaggebend für die Vergabeentscheidung wird, weil allein über den Preiswettbewerb keine qualitätsvollen Ingenieurleistungen zu erlangen sind. — Alternative Vorgehensweise: Der Auftraggeber darf nach § 58 Abs. 2 VgV einen Festpreis vorgeben. Die Festpreisvorgabe muss HOAI-konform sein. Der Preis ist in diesem Fall kein Zuschlagskriterium mehr.', 'derived', NULL, NULL, 'festpreis_used == false', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'price_weight_calc_pct') AND w.code = 'M820-14' AND s.code = 'DWA-M-820-1';
