FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'qualitaets_kriterien_count') AND w.code = 'M820-14' AND s.code = 'DWA-M-820-1';
UPDATE fields f SET widget = 'register', ui_config = '{"title":"Bewertungskommission","subtitle":"§8.4 — überwiegend fachkundig, ungerade Mitgliederzahl, gleiches Stimmrecht; bei VgV-F-Verfahren mindestens zwei Personen","add_label":"+ Mitglied","placement":"bottom","columns":[{"key":"name","label":"Name","type":"text","required":true},{"key":"funktion","label":"Funktion / Rolle","type":"text"},{"key":"sachverstand","label":"Sachverstand","type":"text"},{"key":"stimmberechtigt","label":"Stimmberechtigt","type":"boolean"},{"key":"vorsitz","label":"Vorsitz","type":"boolean"}],"footer":["bewertungskommission_size_calc","bewertungskommission_vorsitz_count","bewertungskommission_stimmberechtigt_count","bewertungskommission_ungerade_code"],"note":"Will der Auftraggeber die Ingenieurleistungen nach Qualitätskriterien vergeben, so muss er eine Bewertungskommission einsetzen, weil über diese der Sachverstand zur Beurteilung der angebotenen Qualität geschaffen werden kann. Insbesondere bei VgV-F-Verfahren hat der öffentliche Auftraggeber gemäß § 58 Abs .5 VgV mindestens zwei Personen für die Wertung einzusetzen. Die Bewertungskommission sollte bereits bei der Vorbereitung des Vergabeverfahrens und bei der Festlegung von Eig-nungs- und Zuschlagskriterien und deren Gewichtung eingebunden werden. Die Bewertungskommission sollte überwiegend fachkundig mit einer ungeraden Mitgliederzahl besetzt sein. Alle Mitglieder haben gleiches Stimmrecht."}'::jsonb, lookup = NULL, visible_when = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'bewertungskommission_members' AND w.code = 'M820-16' AND s.code = 'DWA-M-820-1' AND f.active;
