SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'bewertungskommission_size_calc', 'Anzahl Mitglieder der Bewertungskommission (aus dem Register)', 'number', NULL, false, '§8.4 (§ 58 Abs. 5 VgV)', 'Plan 3: Ausgabe der Gleichung M820-16-D1 (count_rows über bewertungskommission_members); Zwilling zum manuellen bewertungskommission_size (gelesen von REQ-09) — Umstellung STAGED (m820_1-D-14, G-8).', 'imported_unverified', 'Will der Auftraggeber die Ingenieurleistungen nach Qualitätskriterien vergeben, so muss er eine Bewertungskommission einsetzen, weil über diese der Sachverstand zur Beurteilung der angebotenen Qualität geschaffen werden kann. Insbesondere bei VgV-F-Verfahren hat der öffentliche Auftraggeber — gemäß § 58 Abs .5 VgV mindestens zwei Personen für die Wertung einzusetzen. Die Bewertungskommission sollte bereits bei der Vorbereitung des Vergabeverfahrens und bei der Festlegung von Eig-nungs- und Zuschlagskriterien und deren Gewichtung eingebunden werden. Die Bewertungskommission sollte überwiegend fachkundig mit einer ungeraden Mitgliederzahl besetzt sein. Alle Mitglieder haben gleiches Stimmrecht.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'bewertungskommission_size_calc') AND w.code = 'M820-16' AND s.code = 'DWA-M-820-1';
