SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'bewertungskommission_ungerade_code', 'Ungerade Mitgliederzahl (1 = ja, 0 = gerade oder leer) — "sollte"', 'number', NULL, false, '§8.4', 'Plan 3: Ausgabe der Gleichung M820-16-D4 (Anzahl − 2·floor(Anzahl/2) = 1); Empfehlung ("sollte … mit einer ungeraden Mitgliederzahl besetzt sein"), kein Gate.', 'imported_unverified', 'gemäß § 58 Abs .5 VgV mindestens zwei Personen für die Wertung einzusetzen. Die Bewertungskommission sollte bereits bei der Vorbereitung des Vergabeverfahrens und bei der Festlegung von Eig-nungs- und Zuschlagskriterien und deren Gewichtung eingebunden werden. Die Bewertungskommission sollte überwiegend fachkundig mit einer ungeraden Mitgliederzahl besetzt sein. Alle Mitglieder haben gleiches Stimmrecht.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
