FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'applicant_count_calc') AND w.code = 'M820-18' AND s.code = 'DWA-M-820-1';
