SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'shortlisted_count_calc', 'Zur Angebotsphase zugelassene Bewerber (aus dem Register)', 'number', NULL, false, 'Anhang F Nr. 6; § 8.10.3.1', 'Plan 3: Ausgabe der Gleichung M820-18-D2 (count_rows über shortlisted = true); Zwilling zu shortlisted_count (gelesen von REQ-19) — m820_1-D-17 / G-9.', 'imported_unverified', 'Nachdem der Auftraggeber aus allen Bewerbungen gemäß seiner Wertung die vorab bekannt gegebene Zahl geeigneter Bewerber ermittelt hat, werden diese zur Abgabe der Erstangebote aufgefordert und mit ihnen Verhandlungsgespräche geführt. — I die Namen der Bewerber, I die Erklärung, ob die Bewerbungen formal in Ordnung sind, I die erreichte Punktzahl, I die Rangfolge der Bewerber nach Wertung und I die Erklärung, wer zur Angebotsphase zugelassen wird.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'shortlisted_count_calc') AND w.code = 'M820-18' AND s.code = 'DWA-M-820-1';
