SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'final_offers_count_calc', 'Endgültige Angebote (aus dem Register)', 'number', NULL, false, 'Anhang F Nr. 8; § 8.10.3.4', 'Plan 3: Ausgabe der Gleichung M820-18-D3 (count_rows über final_offer = true); Zwilling zu final_offers_count auf M820-19 (konsumiert von M820-23) — m820_1-D-18.', 'imported_unverified', 'Die Bewertungskommission des Auftraggebers bewertet jedes endgültige Angebot gemäß den Zuschlagskriterien. — Hier muss eine Zusammenfassung der Wertung der Bieter (üblicherweise in Tabellenform) dargestellt werden.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'final_offers_count_calc') AND w.code = 'M820-18' AND s.code = 'DWA-M-820-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'winner_count', 'Zeilen mit Zuschlag (Anzahl; genau ein erfolgreicher Bieter)', 'number', NULL, false, 'Anhang F Nr. 9; § 8.10.3.6', 'Plan 3: Ausgabe der Gleichung M820-18-D4 (count_rows über winner = true); Zwilling zum Textfeld winning_bidder auf M820-23 — m820_1-D-19; ein Gate "= 1" ist STAGED (m820_1-G-9).', 'imported_unverified', 'Der Auftraggeber trifft eine Entscheidung über die Zuschlagserteilung an denjenigen Bieter, der gemäß den Zuschlagskriterien die höchste Punktzahl erreicht hat. — Hier müssen der Name des erfolgreichen Bieters und die Gründe für die Auswahl seines Angebots sowie - falls bekannt - der Anteil am Auftrag, den der erfolgreiche Bieter an Dritte weiterzugeben beabsichtigt, genannt werden. Außerdem ist zu begründen, warum die übrigen Angebote der Bieter nicht erfolgreich waren.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'winner_count') AND w.code = 'M820-18' AND s.code = 'DWA-M-820-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'verhandlungsrunden', 'Verhandlungsgespräche (Runde × Bieter, Anhang F Nr. 8)', 'json', NULL, false, '§ 8.10.3.4; Anhang F Nr. 8', 'Plan 3: Zeilen je Verhandlungsgespräch; Ausgaben negotiation_rounds_calc (max Runde, M820-20-D1), verhandlungsgespraeche_count (-D2), protokolle_unsigniert_count (-D3) als Zwillinge zum Skalarsatz negotiation_rounds / verhandlung_datum / verhandlung_thema / verhandlung_ergebnis / protokoll_signiert — Umstellungen und REQ-20 STAGED (m820_1-D-20 … D-24, G-10).', 'imported_unverified', 'Die Verhandlungsrunde schließt sich an die Abgabe des Erstangebots an. Weitere Verhandlungsrunden können folgen. — Eine Tagesordnung, aus der sich der Ablauf der Verhandlungsrunde ergibt, ist vom Auftraggeber zu erstellen. — Das Verhandlungsgespräch jeden Bieters muss zusammengefasst und dargestellt werden sowie die Gründe für die einzelne Bepunktung erläutert werden.', 'register', '{"title":"Verhandlungsgespräche (Runde × Bieter)","subtitle":"§ 8.10.3.4 / Anhang F Nr. 8 — je Verhandlungsgespräch eine Zeile: Runde, Bieter, Datum, Thema, Ergebnis, Protokoll signiert","add_label":"+ Verhandlungsgespräch","placement":"section","columns":[{"key":"runde","label":"Runde","type":"number","required":true,"min":1,"aria_label":"Nummer der Verhandlungsrunde"},{"key":"bieter","label":"Bieter","type":"text","required":true},{"key":"datum","label":"Datum","type":"date"},{"key":"thema","label":"Hauptthema / Tagesordnung","type":"text"},{"key":"ergebnis","label":"Ergebnis / Zusammenfassung","type":"text"},{"key":"protokoll_signiert","label":"Protokoll signiert","type":"boolean"}],"footer":["negotiation_rounds_calc","verhandlungsgespraeche_count","protokolle_unsigniert_count"],"note":"Die Verhandlungsrunde schließt sich an die Abgabe des Erstangebots an. Weitere Verhandlungsrunden können folgen. Eine Tagesordnung, aus der sich der Ablauf der Verhandlungsrunde ergibt, ist vom Auftraggeber zu erstellen. Das Verhandlungsgespräch jeden Bieters muss zusammengefasst und dargestellt werden sowie die Gründe für die einzelne Bepunktung erläutert werden. Anzahl Runden = höchste eingetragene Rundennummer."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'verhandlungsrunden') AND w.code = 'M820-20' AND s.code = 'DWA-M-820-1';
