FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'negotiation_rounds_calc') AND w.code = 'M820-20' AND s.code = 'DWA-M-820-1';
