SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'verhandlungsgespraeche_count', 'Anzahl dokumentierter Verhandlungsgespräche', 'number', NULL, false, 'Anhang F Nr. 8', 'Plan 3: Ausgabe der Gleichung M820-20-D2 (count_rows über verhandlungsrunden) — "Das Verhandlungsgespräch jeden Bieters muss zusammengefasst und dargestellt werden".', 'imported_unverified', 'Das Verhandlungsgespräch jeden Bieters muss zusammengefasst und dargestellt werden sowie die Gründe für die einzelne Bepunktung erläutert werden.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'verhandlungsgespraeche_count') AND w.code = 'M820-20' AND s.code = 'DWA-M-820-1';
