INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'liability_personen_tabd1', 'Deckungssumme Personenschäden nach Tab. D.1 (Anhaltswert aus den geschätzten Baukosten)', 'number', 'EUR', false, 'Anhang D, Tab. D.1; Anhang E.1.4.2', 'Plan 3: Ausgabe der Gleichung M820-22-D1 (Stufenkette über TABD1 nach estimated_construction_cost; Baukosten über 50 Mio. € haben keine gedruckte Zeile → offen, m820_1-J-2); Anhaltswert (RBBau-Empfehlung, L1454 / L1629) neben dem eingetragenen liability_insurance_personenschaden (M820-13) und haftpflicht_versicherungssumme — m820_1-D-1 … D-3.', 'imported_unverified', 'Als Deckungssummen für eine Haftpflichtversicherung empfiehlt das für das Bauwesen zuständige Bundesministerium in seinen Vertragsmustern ${ }^{7)}$ im Wesentlichen folgende Beträge, in Abhängigkeit zu den Herstellungskosten (siehe Tabelle D.1). — Tabelle D.1: Deckungssummen für eine Haftpflichtversicherung in Abhängigkeit zu den Herstellungskosten — \hline Geschätzte Baukosten & Deckungssumme für Personenschäden & Deckungssumme für sonstige Schäden \\', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'liability_personen_tabd1') AND w.code = 'M820-22' AND s.code = 'DWA-M-820-1';
