SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'liability_sonstige_tabd1', 'Deckungssumme sonstige Schäden nach Tab. D.1 (Anhaltswert aus den geschätzten Baukosten)', 'number', 'EUR', false, 'Anhang D, Tab. D.1; Anhang E.1.4.2', 'Plan 3: Ausgabe der Gleichung M820-22-D2 (Stufenkette über TABD1; über 50 Mio. € offen — m820_1-J-2); Anhaltswert neben dem eingetragenen liability_insurance_sonstige (M820-13) — m820_1-D-2.', 'imported_unverified', 'Als Deckungssummen für eine Haftpflichtversicherung empfiehlt das für das Bauwesen zuständige Bundesministerium in seinen Vertragsmustern ${ }^{7)}$ im Wesentlichen folgende Beträge, in Abhängigkeit zu den Herstellungskosten (siehe Tabelle D.1). — Tabelle D.1: Deckungssummen für eine Haftpflichtversicherung in Abhängigkeit zu den Herstellungskosten — \hline Geschätzte Baukosten & Deckungssumme für Personenschäden & Deckungssumme für sonstige Schäden \\', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'liability_sonstige_tabd1') AND w.code = 'M820-22' AND s.code = 'DWA-M-820-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'liability_personen_ok', 'Geforderte Deckungssumme Personenschäden ≥ Tab. D.1 (1 = ja, 0 = darunter)', 'number', NULL, false, 'Anhang D, Tab. D.1; Anhang E.1.4.2', 'Plan 3: Ausgabe der Gleichung M820-22-D3 (liability_insurance_personenschaden ≥ Tab.-D.1-Wert, Kette inline); Vorschlag für REQ-13 (heute leere Bedingung auf M820-10) STAGED (m820_1-G-11) — Anhaltswert, daher warn.', 'imported_unverified', 'Die Höhe der geforderten Versicherungssummen richtet sich nach der Auftragssumme. Anhaltspunkt für die Höhe der geforderten Versicherungssumme kann Tabelle D. 1 in Anhang D geben. Dabei sind für die Festlegung der Höhe auch projektspezifische Risiken abzuschätzen. — Bei diesen Werten ist zu berücksichtigen, dass die versicherte Summe für Personenschäden gemessen an der heutigen Rechtsprechung zum Schadensersatz sehr niedrig ist. Damit der Planer den eventuell darüber hinaus gehenden Schaden nicht selbst zu tragen hat, sollte dieser im Eigeninteresse höhere Deckungsbeträge mit seiner Versicherung vereinbaren.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'liability_personen_ok') AND w.code = 'M820-22' AND s.code = 'DWA-M-820-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'liability_sonstige_ok', 'Geforderte Deckungssumme sonstige Schäden ≥ Tab. D.1 (1 = ja, 0 = darunter)', 'number', NULL, false, 'Anhang D, Tab. D.1; Anhang E.1.4.2', 'Plan 3: Ausgabe der Gleichung M820-22-D4 (liability_insurance_sonstige ≥ Tab.-D.1-Wert, Kette inline); Vorschlag für REQ-13 STAGED (m820_1-G-11).', 'imported_unverified', 'Die Höhe der geforderten Versicherungssummen richtet sich nach der Auftragssumme. Anhaltspunkt für die Höhe der geforderten Versicherungssumme kann Tabelle D. 1 in Anhang D geben. Dabei sind für die Festlegung der Höhe auch projektspezifische Risiken abzuschätzen.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'liability_sonstige_ok') AND w.code = 'M820-22' AND s.code = 'DWA-M-820-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'required_standstill_days_gwb', 'Wartepflicht nach § 134 Abs. 2 GWB (15 Kalendertage; 10 bei elektronischer Versendung)', 'number', 'days', false, '§ 8.10.3.6 (§ 134 Abs. 2 GWB); Anhang B.2.3', 'Plan 3: Tab.-Zwilling neben dem eingetragenen required_standstill_days (konsumiert von M820-24 — Umbindung STAGED m820_1-E-2); Schlüssel = electronic_transmission (Boolean, stringifiziert). REQ-22 prüft standstill_period_days weiterhin je Zweig.', 'imported_unverified', 'Der Auftraggeber darf den Vertrag frühestens 15 Kalendertage (bei Versendung auf elektronischem Weg 10 Kalendertage) nach Absendung dieser Informationen schließen (§ 134 Abs. 2 GWB).', 'lookup_fill', '{"source_label":"§ 134 Abs. 2 GWB (§ 8.10.3.6)"}'::jsonb, '{"table_code":"S8_10_3_6","role":"value","keys":[{"column":"uebermittlung","from_symbol":"electronic_transmission"}],"value":"frist_tage"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'required_standstill_days_gwb') AND w.code = 'M820-23' AND s.code = 'DWA-M-820-1';
COMMIT;
